"""Explicit life/integrity review, current amendments and bounded judicial evidence."""
import json,sys
from pathlib import Path
rows={}
def add(n,text,points,warning,case,variation,qa,term,meaning):
 rows['art-'+str(n)]=dict(simples=text,pontos=points,atencao=[warning],exemplo=case+' Variação: '+variation,prova=qa,termos=[dict(termo=term,significado=meaning)],remissoes=['https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm'])
add(121,'Homicídio simples pune matar alguém com reclusão de 6 a 20 anos. O artigo diferencia privilégio, qualificadoras, forma culposa e aumentos; o contexto de organização ultraviolenta/milícia tem redação especial de 2026, e feminicídio passou ao art. 121-A.', ['Privilégio: 1/6 a 1/3; relevante valor OU domínio de emoção logo após provocação injusta, não mera influência.', 'Qualificado: 12 a 30; identificar motivo, meio, defesa dificultada, conexão, função, arma restrita/proibida, menor14 e instituição de ensino.', 'Lei 15.134: função e familiares com recortes distintos, vigente em 7/5/2025. Lei 15.159: hipótese escolar, vigente em 4/7/2025.', '§2º-D: 20 a 40, Lei 15.358 vigente em 25/3/2026, exige integrante E contexto/finalidade legais.', 'Culposo: detenção1 a3; §4º separa culpa e dolo; §5º perdão na hipótese culposa; §6º milícia/extermínio tem recorte próprio.', 'Menor14: integrar §2º-B; instituição escolar: §2º-C. Não duplicar o mesmo fundamento.'], 'Não ressuscitar incisoVI/§§2º-A/7º revogados como feminicídio atual. Não aplicar aumento por menor14 junto da qualificadora pelo mesmo dado sem enfrentar bis in idem. Pertencer a grupo sozinho não satisfaz contexto/finalidade do §2º-D; mudança gravosa não retroage e controle constitucional não foi certificado integralmente. Privilégio/qualificadoras exigem análise própria, não solução universal.', 'Professor mata aluno nas dependências da escola: a hipótese escolar e o vínculo específico devem ser analisados, sem presumir também toda qualificadora por profissão.', 'Se o fato ocorreu antes das alterações agravadoras, analisar lei no tempo; se ocorreu fora de instituição, falta o pressuposto escolar, ainda que o autor seja professor.', ['Toda emoção basta para o privilégio? Não; domínio, provocação injusta e sequência imediata são requisitos.', 'Membro de facção sozinho prova §2º-D? Não; exige a qualidade legal e o contexto/finalidade.', 'Feminicídio atual permanece no incisoVI? Não; artigo autônomo desde2024.'],'Qualificadora e majorante','Mudanças na espécie ou no aumento da pena, com pressupostos próprios e vedação de dupla contagem.')
add('121-a','Feminicídio é matar mulher por razões da condição do sexo feminino: violência doméstica/familiar OU menosprezo/discriminação. Lei14.994 criou o tipo autônomo de20 a40 anos, publicada e vigente em10/10/2024.', ['§2º: aumento de1/3 até metade nas hipóteses legais, não dobro universal.', 'Gestação,3 meses pós-parto OU mãe/responsável por criança/adolescente/pessoa com deficiência; não limitar esta última situação a3 meses.', 'Presença física OU virtual de descendente/ascendente; idade, deficiência/doença e medidas protetivas têm recortes próprios.', '§2ºV remete a meios/defesa/arma do art.121; §3º comunica as elementares pessoais do §1º ao coautor/partícipe.'], 'Ser mulher, sozinho, não prova as razões legais. Não generalizar qualquer presença de testemunha como ascendente/descendente nem duplicar o mesmo fundamento. A pena nova mais gravosa não retroage; coautoria exige elementos e conhecimento pertinentes, não responsabilidade automática por proximidade.', 'Ascendente da vítima acompanha por videochamada o fato configurado como feminicídio: examinar presença virtual expressamente prevista.', 'Se a pessoa presente é apenas vizinho, essa hipótese de parentesco não está demonstrada; outros elementos precisam de análise própria.', ['Toda morte de mulher é automaticamente feminicídio? Não; exige razões legais.', 'A presença deve ser só física? Não; o texto inclui virtual.'],'Razões da condição do sexo feminino','Elementares previstas no §1º, não rótulo presumido por sexo da vítima.')
add('121-b','Vicaricídio pune matar pessoa indicada vinculada à mulher com finalidade específica de causar-lhe sofrimento, punição ou controle em violência doméstica/familiar. Lei15.384:20 a40 anos, vigente em10/4/2026, texto retificado em15/4/2026.', ['Vítima direta: descendente, ascendente, dependente, enteado ou pessoa sob guarda/responsabilidade direta.', 'Aumento1/3 até metade: presença da mulher, vítima com qualidades indicadas ou descumprimento de medida protetiva.', 'A definição de violência vicária na Maria da Penha é mais ampla que o tipo de matar.'], 'Não equiparar toda violência vicária a homicídio nem ampliar vítimas penais por analogia prejudicial a toda rede de apoio. Finalidade específica e contexto exigem prova. Novo tipo/pena gravosos não retroagem; não certificar todo controle constitucional por existir texto publicado.', 'Agente mata descendente da mulher para puni-la no contexto doméstico: examinar todos os elementos do art.121-B.', 'Violência contra alguém da rede de apoio, sem matar ou sem o vínculo penal listado, não permite afirmar automaticamente este tipo; examinar outros enquadramentos.', ['Qualquer violência vicária configura art.121-B? Não; exige matar e elementos específicos.', 'Todo amigo da rede de apoio consta do rol penal? Não; não ampliar por analogia.'],'Finalidade vicária','Propósito específico de atingir a mulher por vítima vinculada, no contexto legal.')
add(122,'Induzir, instigar ou auxiliar materialmente suicídio/automutilação tem pena-base de6 meses a2 anos e resultados qualificados. A redação de2019 não depende sempre de morte; vítimas especialmente vulneráveis e meios virtuais mudam a análise.', ['Lesão grave/gravíssima:1 a3; morte:2 a6 na hipótese própria.', '§3º duplica por motivo ou vulnerabilidade indicados; §4º meio virtual aumenta ATÉ dobro.', '§5º líder/coordenador/administrador/responsável: dobro, redação Lei14.811 vigente em15/1/2024.', '§6º: gravíssima e vítima indicada remetem a129§2º; §7º: morte e vulnerabilidade indicada remetem a121.'], 'Não reproduzir regra antiga que só punia havendo resultado grave/morte, nem tratar todo usuário de rede como administrador. Até o dobro não é dobro obrigatório. Remissões dos §§6º/7º exigem resultado e qualidades específicas; não deixar enquadramento no art.122 por automatismo.', 'Administrador de grupo virtual realiza a conduta típica: examinar o §5º e prova de sua atuação, sem atribuir o mesmo papel a todos os integrantes.', 'Se há morte de vítima menor14 na hipótese do §7º, analisar homicídio em vez de apenas repetir a faixa geral do §2º.', ['Todo usuário de rede é administrador? Não.', 'Até o dobro equivale a dobro obrigatório? Não; distinguir §§4º/5º.'],'Induzir e instigar','Criar ou reforçar decisão alheia nas condutas típicas, distinto de execução direta do resultado.')
add(127,'Resultados na gestante qualificam as penas dos arts.125/126: aumento de1/3 por lesão grave e duplicação por morte decorrentes do aborto ou meios empregados. Não é regra de duplicação de todo autoaborto.', ['Remissão aos DOIS artigos anteriores:125 e126.', 'Nexo com aborto OU meios utilizados.'], 'Não aplicar ao art.124 apenas pela proximidade no capítulo nem imputar resultado sem nexo e elemento subjetivo exigível; integrar art.19. Consentimento não elimina automaticamente as consequências do resultado na hipótese legal.', 'Aborto provocado por terceiro na hipótese de125/126 causa lesão grave na gestante: examinar aumento de1/3 e requisitos.', 'Se resulta morte da gestante no mesmo nexo legal, a regra prevista é duplicação, não repetir a fração da lesão.', ['A remissão inclui automaticamente art.124? Não; são125/126.', 'Lesão grave e morte têm mesma fração? Não; um terço versus dobro.'],'Resultado agravador','Consequência ligada ao fato/meios, com requisito de imputação e aumento próprio.')
add(128,'O CP prevê hipóteses de aborto praticado por médico: ausência de outro meio de salvar a vida da gestante e gravidez resultante de estupro com consentimento pertinente. ADPF54 afasta criminalização da interrupção por anencefalia diagnosticada, como interpretação judicial própria.', ['IncisoI: não há outro meio de salvar a VIDA, não qualquer risco genérico.', 'IncisoII: consentimento da gestante ou representante quando incapaz.', 'ADPF54, julgamento de2012: decisão da gestante e diagnóstico, sem generalizar a qualquer malformação.', 'ADPFs989/1207: notícia de27/10/2025 relata não referendo da liminar de17/10, não decisão definitiva de todo mérito.'], 'Não dizer que remissão MC no compilado prova liminar vigente: STF não a referendou em24/10/2025. Não certificada aqui inexistência de decisões posteriores ou todo mérito até2026; não usar a cautelar superada como autorização atual universal de atuação da enfermagem. Urgência, consentimento e regulamentação assistencial exigem avaliação própria, sem inventar autorização judicial universal ou permissão geral a qualquer pessoa.', 'Diagnóstico médico de anencefalia e escolha da gestante exigem analisar ADPF54; não restringir toda hipótese jurídica aos dois incisos literais.', 'Se a questão usa a liminar isolada das ADPFs989/1207 para afirmar autorização atual ampla à enfermagem, confrontar não referendo e reconferir eventual andamento posterior.', ['Apenas remissão MC comprova vigência da liminar? Não.', 'Anencefalia equivale a qualquer malformação? Não; a decisão tem recorte próprio.', 'Não referendo da cautelar encerra necessariamente todo mérito? Não.'],'Texto e decisão judicial','Fontes distintas que devem ser integradas com alcance e estado processual explicitados.')
add(129,'Lesão corporal ofende integridade ou saúde e tem modalidades conforme resultado e contexto. Leve:3 meses a1 ano; grave:1 a5; gravíssima:2 a8; seguida de morte:4 a12, sem dolo/assunção do risco de matar. Alterações de2024–2026 têm disciplina própria.', ['Grave: ocupações habituais MAIS de30 dias, perigo de vida, debilidade ou aceleração do parto.', 'Gravíssima: incapacidade permanente para trabalho, enfermidade incurável, perda/inutilização, deformidade ou aborto.', 'Privilégio1/6 a1/3; culpa2 meses a1 ano; §5º contém moeda histórica, não tabela monetária atual.', '§§9º/13:2 a5 após Lei14.994, vigente10/10/2024; Lei15.455 vigente2/7/2026 inclui relação de trabalho doméstico no §9º.', '§12 escolar/função: frações e pressupostos próprios, Lei15.159 vigente4/7/2025.', 'Lei15.358 vigente25/3/2026: §3º-A20 a40; §8º-A2/3 com EXCEÇÃO do §3º-A; §§10/11 e remissões§§7º/8º exigem integração.'], 'Não confundir preterdolo com dolo eventual de matar nem aplicar todas as frações cumulativamente pelo mesmo fundamento. Não usar mil-réis como moeda atual ou duplicar fundamento de menor14 nas remissões. Súmula542/STJ: lesão em violência doméstica contra mulher tem ação pública incondicionada; não impor representação pelo novo prazo geral doméstico. Mudanças gravosas não retroagem.', 'A vítima fica incapaz de ocupações habituais por exatamente30 dias: esse dado não satisfaz MAIS de30, mas outros resultados graves devem ser verificados.', 'Se o agente quis matar ou assumiu o risco, examinar homicídio; não enquadrar sempre como lesão seguida de morte só por haver lesões anteriores.', ['Exatamente30 dias basta nesse inciso? Não.', '§8º-A aplica automaticamente também ao §3º-A? Não; há exceção expressa.', 'A vítima de lesão doméstica contra mulher precisa sempre representar? Não; Súmula542.'],'Resultados da lesão','Consequências e contextos distintos, com classificação e penas próprias.')
add(130,'Perigo de contágio venéreo exige exposição por relação sexual/ato libidinoso e conhecimento indicado da contaminação. A hipótese de intenção de transmitir tem pena própria; o artigo exige representação.', ['Caput:3 meses a1 ano OU multa.', 'Intenção de transmitir:1 a4 E multa.', 'Representação:§2º.'], 'Diagnóstico sozinho não prova exposição, conhecimento ou finalidade. Não estigmatizar toda doença ou importar representação do art.130 para todo delito de contágio; tipo, prova e regime específico importam.', 'Há contaminação conhecida, mas nenhum ato sexual/libidinoso de exposição demonstrado: não presumir consumação só pelo diagnóstico.', 'Se a exposição e intenção específica são provadas na hipótese legal, analisar §1º sem tratar o caput como pena universal.', ['Diagnóstico sozinho basta? Não.', 'As penas usam sempre multa cumulativa? Não; caput alternativa e §1º cumulativa.'],'Exposição ao contágio','Conduta de perigo com meio e elementos próprios, não mera condição de saúde.')
add(131,'Praticar ato capaz de produzir contágio de moléstia grave de que está contaminado, com finalidade de transmiti-la, tem reclusão de1 a4 anos e multa. Diferentemente do art.130, não se limita ao meio sexual.', ['Fim de transmitir E ato capaz.', 'Não importar condição de representação do art.130.'], 'Não presumir dolo específico por doença ou contato social comum nem universalizar enquadramento de toda enfermidade sem verificar elementos e jurisprudência pertinente. Transmissão efetiva não é requisito textual de todo fato de perigo.', 'Pessoa conhece a contaminação, mas não há ato capaz nem finalidade de transmitir demonstrados.', 'Com ato capaz e finalidade legal comprovados, examinar o tipo sem exigir sempre resultado de contágio como único fundamento.', ['Qualquer contato com pessoa doente basta? Não.', 'O texto exige finalidade? Sim; com o fim de transmitir.'],'Fim de transmissão','Elemento específico de propósito, diferente de mera ciência da doença.')
add(132,'Expor vida/saúde a perigo direto e iminente tem detenção de3 meses a1 ano se não houver crime mais grave. Transporte irregular de pessoas para serviços tem aumento próprio; perigo não é presumido por toda irregularidade.', ['Subsidiariedade expressa.', 'Transporte para serviços: aumento1/6 a1/3 com hipótese específica.'], 'Não confundir risco genérico/abstrato com perigo direto e iminente nem usar irregularidade administrativa isolada como prova automática do crime. Crime mais grave e resultado exigem enquadramento próprio.', 'O transporte viola norma, mas a questão presume o delito sem demonstrar perigo direto e iminente.', 'Se a exposição típica é provada no transporte para serviços, examinar parágrafo e subsidiariedade, sem somar automaticamente todo enquadramento.', ['Basta risco remoto genérico? Não; direto e iminente.', 'Se há crime mais grave ignora-se a subsidiariedade? Não.'],'Perigo concreto','Exposição direta e iminente nas condições do tipo.')
add(133,'Abandonar pessoa sob cuidado/guarda/vigilância/autoridade incapaz de defender-se dos riscos tem penas ampliadas pela Lei15.163, publicada e vigente em4/7/2025. Incapacidade pode ter qualquer causa relevante, não apenas idade.', ['Caput2 a5; lesão grave3 a7; morte8 a14 anos de reclusão.', 'Aumento1/3: lugar ermo, vínculo legal ou vítima maior60.', 'Exige relação especial e incapacidade de defesa dos riscos.'], 'Não usar penas antigas como atuais nem aplicá-las de forma gravosa retroativa. Não presumir incapacidade apenas por rótulo ou abandono típico por qualquer afastamento; verificar riscos e elementos. Resultado agravador exige imputação, não mero evento casual.', 'Responsável deixa pessoa incapaz de defender-se exposta aos riscos do abandono, preenchidos os elementos legais.', 'Se não existe a relação especial nem incapacidade indicada, reavaliar enquadramento, inclusive eventual socorro, sem impor automaticamente art.133.', ['Só crianças podem ser vítimas? Não; incapacidade pode decorrer de outras causas.', 'Penas ampliadas retroagem prejudicialmente? Não.'],'Incapacidade no abandono','Inaptidão de defesa diante dos riscos, ligada à relação especial do autor.')
add(134,'Expor/abandonar recém-nascido para ocultar desonra própria tem finalidade específica e resultados qualificados. A expressão histórica não legitima violência, culpa da vítima ou qualquer tese de defesa da honra.', ['Caput6 meses a2; lesão grave1 a3; morte2 a6, detenção.', 'Recém-nascido e finalidade específica são requisitos.'], 'Não confundir com infanticídio, que exige matar e hipótese de estado puerperal, nem com qualquer abandono do art.133. Não presumir desonra ou a finalidade por estereótipo; resultado e elemento subjetivo exigem análise.', 'O recém-nascido é exposto com finalidade específica demonstrada de ocultar desonra própria, no recorte textual.', 'Se não há essa finalidade, examinar outro enquadramento em vez de forçar art.134 por toda exposição de bebê.', ['Qualquer abandono de bebê é sempre art.134? Não.', 'A expressão justifica violência pela honra? Não; é requisito a examinar, não excludente.'],'Finalidade especial','Propósito exigido pelo tipo, sem legitimar preconceito ou violência.')
add(135,'Omissão de socorro abrange falta de assistência possível sem risco pessoal nas hipóteses legais ou falta de pedido de socorro público. Não exige heroísmo, mas risco para assistência direta não elimina automaticamente possibilidade segura de acionar ajuda.', ['Caput1 a6 meses OU multa.', 'Lesão grave: aumenta METADE; morte: TRIPLICA se resultar da omissão.'], 'Não exigir assistência que exponha a risco pessoal nem ignorar alternativa de pedir socorro. Resultado precisa decorrer da omissão; não multiplicar pena só porque o desfecho ocorreu sem nexo relevante.', 'Há risco pessoal em entrar no local, mas é possível acionar socorro com segurança: distinguir assistência direta e pedido de ajuda.', 'Se a pessoa pode ajudar diretamente sem risco, a análise do dever muda, preservadas as hipóteses e elementos legais.', ['Risco na assistência direta dispensa sempre pedir ajuda segura? Não.', 'Toda morte no local triplica sem nexo com omissão? Não; o texto exige resultar dela.'],'Socorro possível','Assistência ou acionamento de ajuda nas condições legais, sem heroísmo obrigatório.')
add('135-a','Condicionar atendimento médico-hospitalar emergencial a garantia ou prévio formulário administrativo configura hipótese legal própria. Não se confunde com cobrança legítima posterior ou qualquer cadastro sem atraso do atendimento.', ['Cheque-caução, promissória OU qualquer garantia; formulário prévio como condição.', 'Caput3 meses a1 ano E multa.', 'Negativa com lesão grave:ATÉ dobro; morte:ATÉ triplo.'], 'Não exigir resultado grave para reconhecer o caput nem converter até o triplo em triplicação obrigatória, como no art.135. Verificar condição imposta, negativa, resultado e nexo no enquadramento aplicável.', 'Emergência só seria atendida após entrega de cheque-caução: identificar condicionamento, não exigir morte como requisito do caput.', 'Cadastro realizado depois, sem condicionar emergência, não é o mesmo fato; cobrança e regras assistenciais têm análise própria.', ['O caput exige sempre morte? Não.', 'Até o triplo é triplo obrigatório? Não; distinguir da redação do art.135.'],'Condicionamento emergencial','Exigência como barreira ao atendimento urgente, com regime penal próprio.')
add(136,'Maus-tratos expõem a perigo pessoa sob autoridade/guarda/vigilância para educação, ensino, tratamento ou custódia, pelos meios descritos. Lei15.163, vigente em4/7/2025, ampliou penas; educação não autoriza castigo físico em criança/adolescente.', ['Caput2 a5; lesão grave3 a7; morte8 a14 anos de reclusão.', 'Menor14: aumenta1/3; exatamente14 não é menor14.', 'Privação de cuidados, trabalho excessivo/inadequado e abuso de correção são hipóteses; integrar ECA18-A.'], 'Não usar abuso de correção como autorização geral de castigo físico moderado. ECA18-A protege contra castigo físico e tratamento cruel/degradante; responsabilidade e distinção de tortura exigem elementos próprios. Mudanças penais gravosas não retroagem; resultado agravador depende de imputação.', 'Responsável priva criança de alimentação indispensável sob pretexto educativo, expondo-a ao perigo nas condições legais.', 'Se há elementos de outro crime mais grave, como tortura, avaliar tipo próprio; chamar o ato de educação não o torna lícito.', ['Educação autoriza castigo físico contra criança? Não; integrar ECA18-A.', 'Vítima exatamente14 preenche menor14? Não; a expressão é estrita.'],'Maus-tratos e educação','Perigo em relação especial, sem transformar disciplina em licença de violência.')
refs={121:['2024/l14994','2024/l14811','2025/l15134','2025/l15159','2026/l15358'],'121-a':['2024/l14994'],'121-b':['2026/l15384'],122:['2024/l14811'],129:['2024/l14994','2025/l15159','2026/l15358','2026/l15455'],133:['2025/l15163'],136:['2025/l15163']}
for n,paths in refs.items():rows['art-'+str(n)]['remissoes'] += ['https://www.planalto.gov.br/ccivil_03/_ato2023-2026/'+p.split('/')[0]+'/lei/'+p.split('/')[1]+'.htm' for p in paths]
rows['art-128']['remissoes'] += ['https://noticias.stf.jus.br/postsnoticias/mes-da-mulher-ha-onze-anos-stf-descriminalizou-a-interrupcao-da-gravidez-de-fetos-anencefalos/','https://noticias.stf.jus.br/postsnoticias/stf-derruba-liminar-que-autorizou-profissionais-de-enfermagem-a-realizar-aborto-legal/']
rows['art-129']['remissoes'].append('https://www.stj.jus.br/docs_internet/SumulasSTJ.pdf')
rows['art-136']['remissoes'].append('https://www.planalto.gov.br/ccivil_03/leis/l8069.htm')
import re
def readable(v):
 if isinstance(v,str):return re.sub(r'(?<=[A-Za-zÀ-ú])(?=\d)', ' ',v)
 if isinstance(v,list):return [readable(x) for x in v]
 if isinstance(v,dict):return {k:readable(x) for k,x in v.items()}
 return v
for r in rows.values():
 for k in r:
  if k!='remissoes':r[k]=readable(r[k])
if __name__=='__main__':
 assert len(rows)==15
 Path(sys.argv[1]).write_text(json.dumps(dict(course_slug='codigo-penal',units=rows),ensure_ascii=False,indent=2)+'\n');print(len(rows),'explicit life/integrity reviews')
